#!/bin/bash
# Mike OS: Amber - new TV logo. Replaces the old TV logo everywhere: wallpaper, login and user
# pictures, the Amber Store / app / start menu icons, the browser's new tab page, the boot splash
# and the installer slides. (The M.I.K.E game's own icon isn't touched.)
#   sudo bash amber-new-logo.sh
set -u
[ "$(id -u)" = 0 ] || { echo "Run this with sudo:  sudo bash $0"; exit 1; }
USER_NAME=${SUDO_USER:-amber}; [ "$USER_NAME" = root ] && USER_NAME=amber
USER_HOME=$(getent passwd "$USER_NAME" | cut -d: -f6)
say() { echo " * $*"; }
run_in_desktop() {
    local pid envs=() v val
    pid=$(pgrep -u "$USER_NAME" -x plasmashell | head -n 1)
    [ -z "$pid" ] && pid=$(pgrep -u "$USER_NAME" -x lxqt-panel | head -n 1)
    [ -z "$pid" ] && return 1
    for v in DISPLAY XAUTHORITY DBUS_SESSION_BUS_ADDRESS XDG_RUNTIME_DIR; do
        val=$(tr '\0' '\n' < "/proc/$pid/environ" | grep "^$v=" | head -n 1)
        [ -n "$val" ] && envs+=("$val")
    done
    sudo -u "$USER_NAME" env "${envs[@]}" setsid "$@" >/dev/null 2>&1 < /dev/null &
}

echo "=== New Mike OS logo ==="
T=$(mktemp -d)
base64 -d <<'AMBER_LOGO_PAYLOAD' | tar -xzf - -C "$T" || { echo "The file is damaged - download it again."; exit 1; }
