e/73/O/53/O/53/P/57/+/P/AEQ1aZMA+C8A
AMBER_LOGO_PAYLOAD

# old copies of the art (user pictures etc.), found by their fingerprint
declare -A NEWFOR
while read -r sha new; do [ -n "$sha" ] && NEWFOR[$sha]=$new; done <<'OLDMAP'
be9ef4f17fbeb2cce59eac66c5af364672acd7573b36438ae585f9dd09e2d991 /usr/share/mikeos-amber/user.png
e41990e10e46b371f3beb4299498d240cb0d0d738329cab86ccfe1da28fef80d /usr/share/plymouth/themes/mikeos-amber/logo.png
99d5c31240edbb11ab6ab553c02fb538a4a8fc901880bc8c4943dd67e5be6951 /usr/share/pixmaps/mikeos-amber.svg
8155b8a1baf78bb852c6822f6bf15738efd3027035c308882ebef98ded809be0 /usr/share/mikeos-amber/installer/slide1.png
77c59ba8de426bfda533c91789367c0aaede3a41a20bdc19fafb11ab4684c754 /usr/share/mikeos-amber/installer/slide2.png
0c955de5d6f2c32be92a2a079888505c8a41e7fa70cee6181640bcaa7f8e704e /usr/share/mikeos-amber/installer/slide3.png
aac995d39033b0daddb76a3b8753326b611a77a1cd618ad9f0c533824fafd531 /usr/share/mikeos-amber/installer/slide4.png

OLDMAP
replace_copy() {   # replace_copy FILE - swaps it if it's one of the old pictures
    local f=$1 sha
    [ -f "$f" ] || return 0
    sha=$(sha256sum "$f" | cut -c1-64)
    if [ -n "${NEWFOR[$sha]:-}" ]; then
        cat "$T${NEWFOR[$sha]}" > "$f" && say "updated $f"
    fi
}

# 1. the art itself (skip the KDE / LXQt bits this computer doesn't have)
count=0
while IFS= read -r -d '' f; do
    rel=${f#$T}
    case "$rel" in
        /usr/share/plasma/look-and-feel/*) [ -d /usr/share/plasma/look-and-feel/org.mikeos.amber ] || continue ;;
        /usr/share/lxqt/themes/amber/*)    [ -d /usr/share/lxqt/themes/amber ] || continue ;;
        /usr/share/plymouth/*)             [ -d /usr/share/plymouth/themes/mikeos-amber ] || continue ;;
    esac
    install -D -m 644 "$f" "$rel" && count=$((count + 1))
done < <(find "$T" -type f -print0)
say "replaced $count logo files"

# 2. copies of the old pictures (your user picture, login screen, installer)
for f in /etc/skel/.face /etc/skel/.face.icon "$USER_HOME/.face" "$USER_HOME/.face.icon" \
         /var/lib/AccountsService/icons/* /usr/share/sddm/faces/*; do
    replace_copy "$f"
done
for d in /etc/calamares/branding /usr/share/calamares/branding; do
    [ -d "$d" ] && while IFS= read -r -d '' f; do replace_copy "$f"; done < <(find "$d" -type f -print0)
done

# 3. let the desktop notice
command -v gtk-update-icon-cache >/dev/null && gtk-update-icon-cache -q -t -f /usr/share/icons/hicolor 2>/dev/null
touch /usr/share/icons/hicolor 2>/dev/null
WP=/usr/share/wallpapers/MikeOS-Amber/contents/images/1920x1080.png
if grep -qs "MikeOS-Amber" "$USER_HOME/.config/pcmanfm-qt/lxqt/settings.conf"; then
    run_in_desktop pcmanfm-qt --set-wallpaper="$WP" --wallpaper-mode=zoom && say "wallpaper refreshed"
fi
if grep -qs "MikeOS-Amber" "$USER_HOME/.config/plasma-org.kde.plasma.desktop-appletsrc" && command -v plasma-apply-wallpaperimage >/dev/null; then
    run_in_desktop plasma-apply-wallpaperimage "$WP" && say "wallpaper refreshed"
fi
command -v kbuildsycoca5 >/dev/null && run_in_desktop kbuildsycoca5 || true

# 4. boot splash lives in the startup image
if dpkg -s plymouth >/dev/null 2>&1 && [ -d /usr/share/plymouth/themes/mikeos-amber ] && command -v update-initramfs >/dev/null; then
    say "updating the boot splash (this can take a minute)..."
    update-initramfs -u >/dev/null 2>&1 && say "boot splash updated"
fi
rm -rf "$T"
say "Done! Log out and back in (or restart) to see the new logo on the start button and in the menus."
